python - <<'PY'
import numpy as np
from PIL import Image
for n in ['head_camera','front_camera']:
 a=np.asarray(Image.open('/app/'+n+'.png'))
 d=np.load('/app/'+n+'_depth.npy').squeeze().astype(float)
 for label,m in [('red',(a[:,:,0]>120)&(a[:,:,0]>a[:,:,1]*1.5)&(a[:,:,0]>a[:,:,2]*1.5)),('blue',(a[:,:,2]>100)&(a[:,:,2]>a[:,:,0]*1.5)&(a[:,:,2]>a[:,:,1]*1.5))]:
  ys,xs=np.where(m)
  if len(xs): print(n,label,'n',len(xs),'bbox',(xs.min(),ys.min(),xs.max(),ys.max()),'center',(xs.mean(),ys.mean()),'depth',np.nanpercentile(d[ys,xs],[0,10,50,90,100]))
PY

